// Validate incoming alert payload and enrich with defaults
// n8n webhook v2 wraps body in $json.body
const raw = $input.first().json;
const body = raw.body || raw;

// Required fields
const required = ['source', 'severity', 'alert_type', 'title', 'message'];
for (const field of required) {
  if (!body[field]) {
    throw new Error(`Missing required field: ${field}`);
  }
}

// Normalize severity to uppercase
const aliases = {WARNING:'WARN',ERROR:'CRITICAL',FATAL:'CRITICAL',OK:'INFO',HEALTHY:'INFO',PASS:'INFO'};
const severity = (aliases[(body.severity||'').toUpperCase()] || (body.severity||'').toUpperCase());
const validSeverities = ['DEBUG', 'INFO', 'WARN', 'CRITICAL'];
if (!validSeverities.includes(severity)) {
  throw new Error(`Invalid severity: ${body.severity}. Must be one of: ${validSeverities.join(', ')}`);
}

// Build enriched alert object
const alert = {
  source: body.source,
  severity: severity,
  alert_type: body.alert_type,
  title: body.title,
  message: body.message,
  bot_name: body.bot_name || body.source,
  metadata: body.metadata || {},
  timestamp: body.timestamp || new Date().toISOString(),
  received_at: new Date().toISOString(),
  alert_id: `${body.source}-${body.alert_type}-${Date.now()}`
};

return [{ json: alert }];

// Deduplication using n8n static data (persists between executions)
const staticData = $getWorkflowStaticData('global');

if (!staticData.alertCache) {
  staticData.alertCache = {};
}

const alert = $input.first().json;

// Create a fingerprint from source + alert_type + title
const crypto = require('crypto');
const fingerprint = crypto
  .createHash('md5')
  .update(`${alert.source}:${alert.alert_type}:${alert.title}`)
  .digest('hex');

const now = Date.now();
const cooldownMs = 30 * 60 * 1000; // 30 minutes

// Clean expired entries
for (const key of Object.keys(staticData.alertCache)) {
  if (now - staticData.alertCache[key] > cooldownMs) {
    delete staticData.alertCache[key];
  }
}

// Check if this alert is a duplicate
if (staticData.alertCache[fingerprint] && (now - staticData.alertCache[fingerprint] < cooldownMs)) {
  return [{ json: { ...alert, is_duplicate: true, fingerprint } }];
} else {
  staticData.alertCache[fingerprint] = now;
  return [{ json: { ...alert, is_duplicate: false, fingerprint } }];
}

// Build Discord webhook payload based on severity
const alert = $input.first().json;

const colors = {
  CRITICAL: 0xED4245,
  WARN: 0xFEE75C,
  INFO: 0x57F287,
  DEBUG: 0x5865F2
};

const emojis = {
  CRITICAL: '🔴',
  WARN: '🟡',
  INFO: '🟢',
  DEBUG: '🔵'
};

const color = colors[alert.severity] || 0x5865F2;
const emoji = emojis[alert.severity] || 'ℹ️';

const embed = {
  title: `${emoji} ${alert.severity} — ${alert.title}`,
  description: alert.message,
  color: color,
  footer: { text: `Source: ${alert.source} | Type: ${alert.alert_type}` },
  timestamp: alert.timestamp,
  fields: [
    { name: 'Severity', value: alert.severity, inline: true },
    { name: 'Bot', value: alert.bot_name, inline: true }
  ]
};

if (alert.severity === 'CRITICAL') {
  embed.fields.push({ name: 'Alert ID', value: alert.alert_id, inline: false });
}

const payload = {
  username: 'Tango Alert Hub',
  embeds: [embed]
};

return [{ json: { ...alert, discord_payload: payload } }];
